"""OrcaCAD - parametric CAD tab for OrcaSlicer (Pages capability).

Adds an "OrcaCAD" tab next to Prepare/Preview/Device. Every model is rendered by
OpenSCAD: catalog objects (Gridfinity from the pinned upstream library plus a
few basic shapes) and free-form OpenSCAD code. The plugin has no Python
dependencies; a verified OpenSCAD build is provisioned per user on first start
when no suitable one is on PATH.

The page is a self-contained React app (frontend/dist/index.html beside this
file, or the compressed copy embedded below for single-file installs). It
talks to this module through window.orca; see ``Session.handle`` for the
message protocol.
"""
from __future__ import annotations

import atexit
import base64
import datetime
import gzip
import hashlib
import importlib.util
import io
import json
import os
import re
import shutil
import subprocess
import sys
import threading
import time
import traceback
import zipfile
from array import array
from collections import deque
from pathlib import Path
from typing import Any, Callable

PLUGIN_VERSION = "0.9.13"
HERE = Path(__file__).resolve().parent
EXPORTS_DIR = HERE / "exports"
CACHE_DIR = HERE / ".cache"
EXPORT_FORMATS = ("stl", "3mf")
PURPOSES = ("preview", "export", "plate")

# BEGIN EMBEDDED OPENSCAD BACKEND
_EMBEDDED_BACKEND = ""
# END EMBEDDED OPENSCAD BACKEND

# BEGIN BUNDLED FRONTEND
_EMBEDDED_FRONTEND = ""
# END BUNDLED FRONTEND

# BEGIN EMBEDDED TAB ICON
_EMBEDDED_ICON = ""
# END EMBEDDED TAB ICON

_BACKEND_ROOT = HERE


def _cache_root() -> Path:
    """Per-user cache directory. Kept short on purpose: the embedded backend has
    93-character vendored paths, and the cloud install directory alone is ~160
    characters, which pushes extraction past Windows' 260-character path limit.

    Inside OrcaSlicer the cache lives in its data directory, derived from the
    plugin's own location because that is the one path OrcaSlicer tells a plugin
    for free. The plugin sandbox pre-approves everything under it, while a cache
    outside it makes OrcaSlicer prompt for permission the user cannot grant for
    good: directory-creation grants are not persisted, and an audited call on a
    worker thread is denied outright, which is what kept the plugin from ever
    unpacking its backend on Windows."""
    for directory in (HERE, *HERE.parents):
        if directory.name.lower() == "orca_plugins":
            return directory.parent / "orcad"
    if sys.platform == "win32":
        base = os.environ.get("LOCALAPPDATA") or Path.home() / "AppData" / "Local"
    elif sys.platform == "darwin":
        base = Path.home() / "Library" / "Caches"
    else:
        base = os.environ.get("XDG_CACHE_HOME") or Path.home() / ".cache"
    return Path(base) / "orcad"


def _load_backend():
    """Import the bundled OpenSCAD backend under a private module name (plugins share one interpreter)."""
    global _BACKEND_ROOT
    root = HERE
    if not (root / "openscad" / "__init__.py").is_file():
        blob = base64.b64decode(_EMBEDDED_BACKEND)
        root = _cache_root() / "backend" / hashlib.sha256(blob).hexdigest()[:16]
        if not (root / "openscad" / "__init__.py").is_file():
            staging = root.with_name(root.name + f".{os.getpid()}.tmp")
            shutil.rmtree(staging, ignore_errors=True)
            try:
                with zipfile.ZipFile(io.BytesIO(gzip.decompress(blob))) as archive:
                    for name in archive.namelist():
                        if name.startswith(("/", "\\")) or ".." in Path(name).parts:
                            raise RuntimeError("invalid embedded backend path")
                    archive.extractall(staging)
            except OSError as exc:  # a full disk, a locked path, an over-long name
                shutil.rmtree(staging, ignore_errors=True)
                raise RuntimeError(f"could not unpack the embedded backend into {staging}: {exc}") from exc
            try:
                staging.rename(root)
            except OSError:
                if (root / "openscad" / "__init__.py").is_file():
                    shutil.rmtree(staging, ignore_errors=True)  # another process won the race
                else:
                    root = staging  # rename blocked (Windows locks); the staging tree is complete
    _BACKEND_ROOT = root
    package = root / "openscad"
    spec = importlib.util.spec_from_file_location(
        "orcad_openscad", package / "__init__.py", submodule_search_locations=[str(package)])
    module = importlib.util.module_from_spec(spec)
    sys.modules["orcad_openscad"] = module
    spec.loader.exec_module(module)
    return module


scad = _load_backend()


def _load_ai_backend():
    package = _BACKEND_ROOT / "ai"
    if not (package / "__init__.py").is_file():
        class MissingAIAgent:
            def __init__(self, post, **_kwargs):
                self.post = post

            def status(self):
                return {"type": "ai_status", "state": "error", "message": "Update OrcaCAD to enable AI coding.",
                        "progress": None, "node_version": None, "pi_version": None, "busy": False,
                        "config": {"source": "pi", "provider": None, "model": None, "thinking": None, "has_key": False},
                        "models": []}

            def setup(self):
                pass

            def configure(self, _msg):
                self.post(self.status())

            def prompt(self, run_id, _text, code):
                self.post({"type": "ai_done", "id": run_id, "ok": False,
                           "error": "Update OrcaCAD to enable AI coding.", "code": code if isinstance(code, str) else ""})
                return True

            def abort(self, _run_id):
                pass

            def reset(self):
                pass

            def close(self):
                pass

        return type("MissingAIBackend", (), {"PiAgent": MissingAIAgent})
    spec = importlib.util.spec_from_file_location(
        "orcad_ai", package / "__init__.py", submodule_search_locations=[str(package)])
    if spec is None or spec.loader is None:
        raise ImportError("the bundled AI backend is missing")
    module = importlib.util.module_from_spec(spec)
    sys.modules["orcad_ai"] = module
    spec.loader.exec_module(module)
    return module


ai_backend = _load_ai_backend()


def page_html() -> str:
    asset = HERE / "frontend" / "dist" / "index.html"
    if asset.is_file():
        return asset.read_text(encoding="utf-8")
    return gzip.decompress(base64.b64decode(_EMBEDDED_FRONTEND)).decode("utf-8")


def _icon_path() -> str:
    """Absolute path to the tab icon, or "" when it cannot be materialised.

    OrcaSlicer resolves this path itself (an SVG first, then a PNG, scaled to the
    tab height) and simply draws no icon when it is empty, so every failure here
    is non-fatal.
    """
    for candidate in (HERE / "orcad-icon.png", HERE / "orcad-icon.svg"):
        if candidate.is_file():
            return str(candidate)  # a real file beside the plugin wins, like the backend
    if not _EMBEDDED_ICON:
        return ""
    try:
        blob = gzip.decompress(base64.b64decode(_EMBEDDED_ICON))
        target = _cache_root() / "orcad-icon.png"
        if not target.is_file() or target.read_bytes() != blob:
            target.parent.mkdir(parents=True, exist_ok=True)
            staging = target.with_name(target.name + f".{os.getpid()}.tmp")
            staging.write_bytes(blob)
            os.replace(staging, target)
        return str(target)
    except Exception:  # a read-only cache, a full disk: the tab just gets no icon
        return ""


# --------------------------------------------------------------------------
# Exports and handing files to OrcaSlicer
# --------------------------------------------------------------------------

def export_path(name: str, fmt: str) -> Path:
    stem = re.sub(r"[^A-Za-z0-9_-]+", "_", str(name or "model")).strip("_")[:60] or "model"
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
    EXPORTS_DIR.mkdir(parents=True, exist_ok=True)
    path, n = EXPORTS_DIR / f"{stem}_{stamp}.{fmt}", 1
    while path.exists():
        path, n = EXPORTS_DIR / f"{stem}_{stamp}_{n}.{fmt}", n + 1
    return path


def write_export(stl: Path, fmt: str, name: str) -> Path:
    target = export_path(name, fmt)
    temp = target.with_name(f".{target.name}.tmp")
    try:
        if fmt == "3mf":
            scad.write_3mf(scad.index_stl(stl.read_bytes()), temp)
        else:
            shutil.copyfile(stl, temp)
        os.replace(temp, target)
    finally:
        temp.unlink(missing_ok=True)
    return target


def _host_executable() -> str:
    if sys.platform == "win32":
        try:
            import ctypes
            buffer = ctypes.create_unicode_buffer(32768)
            # NULL asks Windows for this process's image path (OrcaSlicer.exe),
            # not the Python extension/DLL that hosts the embedded interpreter.
            if ctypes.windll.kernel32.GetModuleFileNameW(None, buffer, len(buffer)):
                return buffer.value
        except Exception:
            pass
    elif sys.platform.startswith("linux"):
        appimage = os.environ.get("APPIMAGE")
        if appimage and os.path.isfile(appimage):
            return appimage
        try:
            return os.readlink("/proc/self/exe")
        except OSError:
            pass
    return sys.executable or ""


def orca_open_command() -> list[str] | None:
    """Command that hands a file to the *running* OrcaSlicer, or None for the OS default."""
    exe = _host_executable()
    if sys.platform == "darwin":
        app = next((p for p in Path(exe).parents if p.suffix == ".app"), None)
        return ["open", "-a", str(app)] if app else ["open"]
    if "orca" in Path(exe).name.lower():
        # CLI setup rejects --single-instance; GUI startup routes positional files
        # through its configured single-instance handler.
        return [exe]
    return None


def _windows_instance_payload(path: Path) -> str:
    # OrcaSlicer parses argv using escape_strings_cstyle(): quoted arguments separated by ';'.
    args = [_host_executable(), os.fspath(path)]
    return ";".join('"%s"' % arg.replace("\\", "\\\\").replace('"', '\\"') for arg in args)


def _windows_copydata_handoff(path: Path) -> tuple[bool, str]:
    """Forward a model to this process's Orca window; call only from the render worker.

    SendMessageW blocks while Orca's UI thread handles WM_COPYDATA. Calling it from
    on_message would deadlock; the plate job reaches here only from Session._work.
    """
    import ctypes
    from ctypes import wintypes

    user32 = ctypes.WinDLL("user32", use_last_error=True)

    class CopyData(ctypes.Structure):
        _fields_ = [("dwData", ctypes.c_size_t),  # ULONG_PTR
                    ("cbData", wintypes.DWORD),
                    ("lpData", ctypes.c_void_p)]

    user32.GetClassNameW.argtypes = (wintypes.HWND, wintypes.LPWSTR, ctypes.c_int)
    user32.GetPropW.argtypes = (wintypes.HWND, wintypes.LPCWSTR)
    user32.GetPropW.restype = wintypes.HANDLE
    user32.GetWindowThreadProcessId.argtypes = (wintypes.HWND, ctypes.POINTER(wintypes.DWORD))
    user32.SendMessageW.argtypes = (wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM)
    user32.SendMessageW.restype = ctypes.c_ssize_t

    enum_proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
    windows = []

    def visit(hwnd, _lparam):
        class_name = ctypes.create_unicode_buffer(256)
        if user32.GetClassNameW(hwnd, class_name, len(class_name)) == 0 or class_name.value != "wxWindowNR":
            return True
        # The instance hash distinguishes Orca installs in other processes. Since
        # this plugin runs inside its target Orca process, its PID is the exact match.
        if not user32.GetPropW(hwnd, "Instance_Hash_Minor") or not user32.GetPropW(hwnd, "Instance_Hash_Major"):
            return True
        pid = wintypes.DWORD()
        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        if pid.value != os.getpid():
            return True
        windows.append(hwnd)
        return False

    user32.EnumWindows.argtypes = (enum_proc, wintypes.LPARAM)
    user32.EnumWindows.restype = wintypes.BOOL
    callback = enum_proc(visit)  # keep the callback alive through EnumWindows
    user32.EnumWindows(callback, 0)
    if not windows:
        return False, "no OrcaSlicer main window found in this process"

    text = ctypes.create_unicode_buffer(_windows_instance_payload(path))
    data = CopyData(1, ctypes.sizeof(text), ctypes.cast(text, ctypes.c_void_p))
    if not user32.SendMessageW(windows[0], 0x004A, 0, ctypes.addressof(data)):
        return False, "OrcaSlicer did not accept WM_COPYDATA"
    return True, ""


def send_to_orca(path: Path) -> dict[str, Any]:
    direct_error = ""
    if sys.platform == "win32":
        try:
            sent, direct_error = _windows_copydata_handoff(path)
            if sent:
                return {"ok": True, "message": "Sent the STL to the running OrcaSlicer window. "
                                                   "Switch to Prepare and check that it appeared."}
        except Exception as exc:
            direct_error = str(exc)

    fallback_note = f"Direct Windows handoff failed ({direct_error}). " if direct_error else ""
    try:
        command = orca_open_command()
        if command:
            options = {
                "stdin": subprocess.DEVNULL, "stdout": subprocess.DEVNULL,
                "stderr": subprocess.DEVNULL, "close_fds": True,
            }
            if sys.platform == "win32":
                # Avoid briefly creating a console if this install uses a console wrapper.
                options["creationflags"] = subprocess.CREATE_NO_WINDOW
            else:
                options["start_new_session"] = True
            process = subprocess.Popen([*command, str(path)], **options)
        elif sys.platform == "win32":
            os.startfile(str(path))  # noqa: S606 - user-requested local file open
            return {"ok": True, "message": fallback_note + "Requested Windows to open the saved STL. Check the plate; "
                                                           "if it is missing, drag the file from exports onto Prepare."}
        else:
            process = subprocess.Popen(["xdg-open", str(path)], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                                       stderr=subprocess.DEVNULL, start_new_session=True, env=scad.child_env())
        try:
            exit_code = process.wait(timeout=2)
        except subprocess.TimeoutExpired:
            return {"ok": True, "message": fallback_note +
                    "The OrcaSlicer launch is still running. Check Prepare; the STL is saved in exports if needed."}
        if exit_code in (-1, 0xFFFFFFFF):
            return {"ok": True, "message": fallback_note +
                    "OrcaSlicer exited after its single-instance forwarding path. Check Prepare; "
                    "the STL is saved in exports if needed."}
        if exit_code != 0:
            return {"ok": False, "message": fallback_note +
                    f"The file-open fallback exited with status {exit_code}. "
                    "The STL is saved in exports; drag it onto Prepare instead."}
    except Exception as exc:
        return {"ok": False, "message": fallback_note + f"Could not hand the file to OrcaSlicer ({exc}). "
                                                           "Drag it from the exports folder onto the plate instead."}
    return {"ok": True, "message": fallback_note + "OrcaSlicer's fallback launch process exited successfully; "
                                                "the plate import itself cannot be confirmed. Check Prepare, or drag "
                                                "the saved STL from exports if missing."}


def open_folder(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)
    if sys.platform == "win32":
        os.startfile(str(path))  # noqa: S606
    else:
        # A scrubbed env keeps an OrcaSlicer AppImage's libraries out of the file manager.
        subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", str(path)],
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         env=scad.child_env())


# --------------------------------------------------------------------------
# Rendering session
# --------------------------------------------------------------------------

def _b64(data: bytes) -> str:
    return base64.b64encode(data).decode("ascii")


def mesh_payload(stl: bytes) -> dict[str, Any]:
    """Compact indexed mesh: little-endian float32 positions + uint16/32 indices, base64."""
    mesh = scad.index_stl(stl)
    wide = len(mesh.positions) // 3 > 0xFFFF
    indices = mesh.indices if wide else array("H", mesh.indices)
    return {"positions": _b64(mesh.positions.tobytes()), "indices": _b64(indices.tobytes()),
            "index_type": "uint32" if wide else "uint16"}


class Job:
    def __init__(self, msg: dict[str, Any]):
        self.id = msg.get("id")
        if type(self.id) is not int:
            raise ValueError("request id must be an integer")
        self.purpose = msg.get("purpose", "preview")
        if self.purpose not in PURPOSES:
            raise ValueError(f"unknown purpose {self.purpose!r}")
        self.quality = msg.get("quality", "balanced")
        if self.quality not in scad.QUALITY_PROFILES:
            raise ValueError(f"unknown quality {self.quality!r}")
        self.format = "stl" if self.purpose == "plate" else msg.get("format", "stl")
        if self.format not in EXPORT_FORMATS:
            raise ValueError(f"unknown export format {self.format!r}")
        self.object = msg.get("object")
        self.params = msg.get("params") or {}
        self.code = msg.get("code")
        if self.object is None and not isinstance(self.code, str):
            raise ValueError("a render needs an object or code")
        if self.object is not None:
            scad.object_spec(self.object)
            if not isinstance(self.params, dict):
                raise ValueError("params must be an object")
        self.name = str(msg.get("name") or self.object or "model")
        self.cancelled = threading.Event()


class Session:
    """Routes page messages. One worker renders serially; the newest preview wins."""

    def __init__(self, post: Callable[[dict[str, Any]], None]):
        self.post = post
        self._cond = threading.Condition()
        self._preview: Job | None = None
        self._exports: deque[Job] = deque()
        self._active: Job | None = None
        self._runner = None
        self._thread: threading.Thread | None = None
        self._ai = ai_backend.PiAgent(self.post, library=scad.LIBRARY_DIR, root=_cache_root() / "ai",
                                      openscad=lambda: str(self._runner.engine.executable) if self._runner
                                      else str(scad.wait_for_openscad()))
        atexit.register(self.shutdown)

    def shutdown(self) -> None:
        self._ai.close()

    # -- page -> plugin ---------------------------------------------------
    def handle(self, msg: Any) -> dict[str, Any] | None:
        if isinstance(msg, str):
            try:
                msg = json.loads(msg)
            except ValueError:
                msg = None
        if not isinstance(msg, dict):
            return {"type": "error", "message": "messages must be JSON objects"}
        kind = msg.get("type")
        if kind == "hello":
            return {"type": "hello", "version": PLUGIN_VERSION, "engine": self.engine_status(),
                    "exports_dir": str(EXPORTS_DIR)}
        if kind == "engine":
            return {"type": "engine", **self.engine_status()}
        if kind == "render":
            try:
                job = Job(msg)
            except (ValueError, scad.BackendError) as exc:
                return {"type": "result", "id": msg.get("id"), "purpose": msg.get("purpose"), "ok": False,
                        "error": str(exc)}
            self.submit(job)
            return None
        if kind == "cancel":
            self.cancel(msg.get("id"))
            return None
        if kind == "ai_status":
            return self._ai.status()
        if kind == "ai_setup":
            self._ai.setup()
            return self._ai.status()
        if kind == "ai_config":
            self._ai.configure(msg)
            return self._ai.status()
        if kind == "ai_auth":
            if not self._ai.authenticate(msg.get("action"), msg.get("provider"), msg.get("auth_type")):
                return {"type": "ai_auth_done", "ok": False, "message": "Switch to OrcaCAD-managed mode or finish the current operation."}
            return None
        if kind == "ai_auth_response":
            self._ai.respond_auth(msg)
            return None
        if kind == "ai_auth_cancel":
            self._ai.cancel_auth()
            return None
        if kind == "ai_provider_detect":
            if not self._ai.detect_custom_models(msg):
                return {"type": "ai_provider_detect_result", "id": msg.get("id"), "ok": False,
                        "error": "Switch to OrcaCAD-managed mode or finish the current operation."}
            return None
        if kind == "ai_provider_save":
            if not self._ai.save_custom_provider(msg):
                return {"type": "ai_provider_result", "action": "save", "id": msg.get("id"), "ok": False,
                        "error": "Switch to OrcaCAD-managed mode or finish the current operation."}
            return None
        if kind == "ai_provider_remove":
            if not self._ai.remove_custom_provider(msg):
                return {"type": "ai_provider_result", "action": "remove", "id": msg.get("id"), "ok": False,
                        "error": "Switch to OrcaCAD-managed mode or finish the current operation."}
            return None
        if kind == "ai_prompt":
            run_id = msg.get("id")
            if not self._ai.prompt(run_id, msg.get("text"), msg.get("code")):
                return {"type": "ai_done", "id": run_id, "ok": False, "error": "busy",
                        "code": msg.get("code", "") if isinstance(msg.get("code"), str) else ""}
            return None
        if kind == "ai_abort":
            self._ai.abort(msg.get("id"))
            return None
        if kind == "ai_reset":
            self._ai.reset()
            return None
        if kind == "open_exports":
            try:
                open_folder(EXPORTS_DIR)
                return {"type": "notice", "ok": True, "message": "Opened the exports folder."}
            except Exception as exc:
                return {"type": "notice", "ok": False, "message": f"Could not open {EXPORTS_DIR}: {exc}"}
        return {"type": "error", "message": f"unknown message type {kind!r}"}

    def engine_status(self) -> dict[str, Any]:
        if self._runner is not None:
            return {"state": "ready", "version": self._runner.engine.version, "progress": None, "error": None}
        status = scad.openscad_bootstrap_status()
        return {"state": status["state"], "version": None, "progress": status["progress"],
                "error": status["error"]}

    # -- queue ---------------------------------------------------------------
    def submit(self, job: Job) -> None:
        with self._cond:
            if job.purpose == "preview":
                if self._preview is not None:
                    self._preview.cancelled.set()
                if self._active is not None and self._active.purpose == "preview":
                    self._active.cancelled.set()
                self._preview = job
            else:
                self._exports.append(job)
            if self._thread is None or not self._thread.is_alive():
                self._thread = threading.Thread(target=self._work, name="orcad-render", daemon=True)
                self._thread.start()
            self._cond.notify()

    def cancel(self, job_id: Any) -> None:
        with self._cond:
            for job in (self._preview, self._active, *self._exports):
                if job is not None and job.id == job_id:
                    job.cancelled.set()

    def _work(self) -> None:
        while True:
            with self._cond:
                while self._preview is None and not self._exports:
                    self._cond.wait()
                if self._exports:
                    job = self._exports.popleft()
                else:
                    job, self._preview = self._preview, None
                self._active = job
            try:
                if not job.cancelled.is_set():
                    self._run(job)
            except scad.BackendError as exc:
                if exc.code != scad.ErrorCode.CANCELLED and not job.cancelled.is_set():
                    self._fail(job, exc.message, exc.code, exc.details)
            except Exception as exc:  # keep the worker alive; the traceback lands in Orca's python log
                traceback.print_exc()
                if not job.cancelled.is_set():
                    self._fail(job, f"Unexpected error: {exc}", "internal_error", {})
            finally:
                with self._cond:
                    self._active = None

    def _fail(self, job: Job, message: str, code: str, details: dict[str, Any]) -> None:
        self.post({"type": "result", "id": job.id, "purpose": job.purpose, "ok": False, "error": message,
                   "error_code": code, "fields": details.get("fields", []), "line": details.get("line"),
                   "log": details.get("log", [])})

    def _progress(self, job: Job, message: str, progress: float | None = None) -> None:
        if not job.cancelled.is_set():
            self.post({"type": "progress", "id": job.id, "purpose": job.purpose, "message": message,
                       "progress": progress})

    def _engine(self, job: Job):
        if self._runner is not None:
            return self._runner
        scad.start_openscad_bootstrap(root=_cache_root() / "openscad")
        last = 0.0
        while (status := scad.openscad_bootstrap_status())["state"] == "starting":
            if job.cancelled.is_set():
                raise scad.BackendError(scad.ErrorCode.CANCELLED, "cancelled")
            if time.monotonic() - last > 0.5:
                last = time.monotonic()
                pct = status["progress"]
                self._progress(job, "Preparing OpenSCAD…" if pct is None
                               else f"Downloading OpenSCAD (one-time setup) {pct:.0%}", pct)
            time.sleep(0.1)
        if status["state"] != "ready":
            raise scad.BackendError(scad.ErrorCode.INSTALL_FAILED, status["error"] or "OpenSCAD is unavailable",
                                    status["error_details"] or {})
        self._runner = scad.OpenSCADRunner(status["path"], cache_dir=CACHE_DIR)
        self.post({"type": "engine", **self.engine_status()})
        return self._runner

    def _run(self, job: Job) -> None:
        runner = self._engine(job)
        self._progress(job, "Rendering…" if job.purpose == "preview" else f"Rendering for {job.format.upper()}…")
        if job.object is not None:
            result = runner.render_object(job.object, job.params, job.quality, cancel=job.cancelled.is_set)
        else:
            result = runner.render_code(job.code, job.quality, cancel=job.cancelled.is_set)
        if job.cancelled.is_set():
            return
        reply = {"type": "result", "id": job.id, "purpose": job.purpose, "ok": True, "quality": job.quality,
                 "triangles": result.triangles, "duration_ms": result.duration_ms, "cached": result.cached,
                 "log": result.log, "engine": runner.engine.version}
        if job.purpose == "preview":
            reply["mesh"] = mesh_payload(result.stl.read_bytes())
        else:
            path = write_export(result.stl, job.format, job.name)
            reply.update(file=str(path), filename=path.name, format=job.format, size_bytes=path.stat().st_size)
            if job.purpose == "plate":
                self._progress(job, "Sending to OrcaSlicer…")
                reply["handoff"] = send_to_orca(path)
        if not job.cancelled.is_set():
            self.post(reply)


# --------------------------------------------------------------------------
# OrcaSlicer wiring
# --------------------------------------------------------------------------

try:
    import orca  # type: ignore[import-not-found]  # provided by OrcaSlicer's embedded interpreter
except ImportError:  # unit tests and the dev server run without OrcaSlicer
    orca = None

if orca is not None:  # pragma: no cover - only inside OrcaSlicer
    _PagesBase = getattr(getattr(orca, "pages", None), "PagesPluginCapabilityBase", None)

    if _PagesBase is not None:
        class OrcadPage(_PagesBase):
            def get_name(self):
                return "OrcaCAD"

            def get_icon(self):
                return _icon_path()

            def get_ui(self):
                return page_html()

            def __del__(self):
                session = getattr(self, "_orcad_session", None)
                if session is not None:
                    session.shutdown()

            def on_message(self, msg):
                session = getattr(self, "_orcad_session", None)
                if session is None:
                    session = self._orcad_session = Session(self.post_message)
                try:
                    reply = session.handle(msg)
                except Exception as exc:
                    traceback.print_exc()
                    reply = {"type": "error", "message": f"OrcaCAD failed to handle a message: {exc}"}
                if reply is not None:
                    self.post_message(reply)

        @orca.plugin
        class OrcadPlugin(orca.base):
            def register_capabilities(self):
                scad.start_openscad_bootstrap(root=_cache_root() / "openscad")
                orca.register_capability(OrcadPage)
    else:
        class OrcadNeedsPages(orca.script.ScriptPluginCapabilityBase):
            def get_name(self):
                return "OrcaCAD (needs a newer OrcaSlicer)"

            def execute(self):
                return orca.ExecutionResult.failure(
                    orca.PluginResult.RecoverableError,
                    "OrcaCAD needs an OrcaSlicer build with plugin pages (orca.pages). Please update OrcaSlicer.")

        @orca.plugin
        class OrcadPlugin(orca.base):
            def register_capabilities(self):
                orca.register_capability(OrcadNeedsPages)
